"""Unpack the reviewed source/test bundle; checksum failure stops the build."""
from pathlib import Path
import base64,hashlib,json,zlib
ROOT=Path(__file__).resolve().parents[1]
PAYLOAD=''
raw=zlib.decompress(base64.b64decode(PAYLOAD))
assert hashlib.sha256(raw).hexdigest()=='153345d9da6c7c20a4992b042db56bfd88537f40f0176fe5fd0ffaf0112ef925'
files=json.loads(raw)
assert set(files)=={'src/cityhill-pno-guard.js','scripts/build_cityhill644.py','tests/test_cityhill644.py'}
for name,content in files.items():
    target=ROOT/name
    target.parent.mkdir(parents=True,exist_ok=True)
    target.write_text(content)
print('Verified reviewed CITYHILL 6.44 source and tests')
